import json
import os

PRED_JSON = 'pred_results/pred_reconstructed_ES_imagenet.json'
PRED_TXT = 'pred_results/pred_reconstructed_ES_imagenet.txt'


def eval():
    # Check that both predicted output files exist
    for path, name in [(PRED_JSON, "JSON"), (PRED_TXT, "TXT")]:
        if not os.path.exists(path):
            return (False, f"Predicted {name} file not found: {path}")

    # Load JSON file
    try:
        with open(PRED_JSON, 'r') as <local-path>            pred = json.load(f)
    except (json.JSONDecodeError, Exception) as <local-path>        return (False, f"Failed to parse predicted JSON: {e}")

    # Check that predicted TXT file is non-empty and has meaningful content
    try:
        with open(PRED_TXT, 'r') as <local-path>            pred_txt = f.read().strip()
        if len(pred_txt) < 50:
            return (False, "Predicted TXT file is too short or empty")
    except Exception as <local-path>        return (False, f"Failed to read predicted TXT: {e}")

    # Check TXT has some meaningful content about the dataset
    txt_lower = pred_txt.lower()
    has_dataset_info = any(kw in txt_lower for kw in ['dataset', 'train', 'val', 'shape', 'label', 'imagenet', 'es-imagenet'])
    if not has_dataset_info:
        return (False, "TXT file doesn't contain expected dataset information")

    def extract_dataset_info(pred):
        """
        Try to extract dataset sizes and sample info from various JSON formats.
        Handles multiple possible structures flexibly.
        """
        train_size = None
        val_size = None
        train_shape = None
        val_shape = None
        train_label = None
        val_label = None

        def search_nested(obj, key_hints, value_type=None):
            """Recursively search for a value by key hints."""
            if isinstance(obj, dict):
                for k, v in obj.items():
                    k_lower = k.lower()
                    if any(hint in k_lower for hint in key_hints):
                        if value_type is None or isinstance(v, value_type):
                            return v
                    result = search_nested(v, key_hints, value_type)
                    if result is not None:
                        return result
            elif isinstance(obj, list):
                for item in obj:
                    result = search_nested(item, key_hints, value_type)
                    if result is not None:
                        return result
            return None

        # Try to find train size
        # Look for keys containing 'train' with a 'length' or 'size' sub-key
        for k, v in pred.items():
            k_lower = k.lower()
            if 'train' in k_lower and 'val' not in k_lower:
                if isinstance(v, dict):
                    for sub_k, sub_v in v.items():
                        if sub_k.lower() in ('length', 'size', 'count', 'num_samples', 'total'):
                            if isinstance(sub_v, int):
                                train_size = sub_v
                        if sub_k.lower() in ('sample_shape', 'shape', 'tensor_shape'):
                            train_shape = sub_v
                        if sub_k.lower() in ('sample_label', 'label', 'class_label'):
                            train_label = sub_v
                elif isinstance(v, int) and v > 0:
                    train_size = v
                elif isinstance(v, list):
                    train_size = len(v)
            elif 'val' in k_lower:
                if isinstance(v, dict):
                    for sub_k, sub_v in v.items():
                        if sub_k.lower() in ('length', 'size', 'count', 'num_samples', 'total'):
                            if isinstance(sub_v, int):
                                val_size = sub_v
                        if sub_k.lower() in ('sample_shape', 'shape', 'tensor_shape'):
                            val_shape = sub_v
                        if sub_k.lower() in ('sample_label', 'label', 'class_label'):
                            val_label = sub_v
                elif isinstance(v, int) and v > 0:
                    val_size = v
                elif isinstance(v, list):
                    val_size = len(v)

        # Fallback: search for any integer that looks like a dataset size
        if train_size is None and val_size is None:
            # Try flat keys
            for k, v in pred.items():
                k_lower = k.lower()
                if isinstance(v, int) and v > 0:
                    if 'train' in k_lower and 'val' not in k_lower:
                        train_size = v
                    elif 'val' in k_lower:
                        val_size = v

        # Another fallback: look for 'length' or 'size' anywhere
        if train_size is None and val_size is None:
            lengths = []
            for k, v in pred.items():
                if isinstance(v, dict):
                    for sub_k, sub_v in v.items():
                        if sub_k.lower() in ('length', 'size') and isinstance(sub_v, int):
                            lengths.append((k, sub_v))
            if len(lengths) >= 2:
                # Assume first is train, second is val
                train_size = lengths[0][1]
                val_size = lengths[1][1]
            elif len(lengths) == 1:
                train_size = lengths[0][1]

        return train_size, val_size, train_shape, val_shape, train_label, val_label

    train_size, val_size, train_shape, val_shape, train_label, val_label = extract_dataset_info(pred)

    # At least one dataset size should be present
    if train_size is None and val_size is None:
        return (False, f"JSON doesn't contain recognizable dataset size information. "
                       f"JSON keys found: {list(pred.keys())}")

    # Verify dataset sizes are reasonable (positive)
    if train_size is not None and train_size <= 0:
        return (False, f"Train dataset size is not positive: {train_size}")
    if val_size is not None and val_size <= 0:
        return (False, f"Val dataset size is not positive: {val_size}")

    # Check sample shapes if available - should be 224x224
    shapes_info = []
    for shape_name, shape_val in [('train', train_shape), ('val', val_shape)]:
        if shape_val is not None:
            shape_list = list(shape_val)
            shapes_info.append(f"{shape_name}_shape={shape_list}")
            # Last two dims should be 224x224
            if len(shape_list) >= 2:
                if shape_list[-1] != 224 or shape_list[-2] != 224:
                    return (False, f"{shape_name} sample shape doesn't end with 224x224, got {shape_list}")

    # Check that 224 is mentioned somewhere (shape verification)
    shape_mentioned = '224' in pred_txt or '224' in json.dumps(pred)

    # Build success message
    success_parts = []
    if train_size is not None:
        success_parts.append(f"train_size={train_size}")
    if val_size is not None:
        success_parts.append(f"val_size={val_size}")
    if train_label is not None:
        success_parts.append(f"train_label={train_label}")
    if val_label is not None:
        success_parts.append(f"val_label={val_label}")
    success_parts.extend(shapes_info)
    if shape_mentioned:
        success_parts.append("224x224 shape confirmed")

    return (True, f"Evaluation passed: {', '.join(success_parts)}. "
                  f"JSON and TXT files present with valid dataset information.")


if __name__ == "__main__":
    result, reason = eval()
    print(f"Result: {result}")
    print(f"Reason: {reason}")

import os
import re
import math


def parse_dinfo_flexible(filepath):
    """
    Parse a pred_dinfo.txt file flexibly.
    Supports multiple formats:
    1. One line per frame: energy d7[0..6] d3[0..2]  (11 values per line)
    2. Labeled format with 'Total energy:', 'D (7 element vector):', 'D (3 element vector):'
    3. Any reasonable structured format with energy + 7 + 3 values
    """
    with open(filepath, 'r') as <local-path>        content = f.read()

    lines = [line.strip() for line in content.strip().split('\n') if line.strip()]

    # Try format 1: labeled format with section headers
    if 'Total energy:' in content or 'D (7 element vector)' in content:
        return parse_labeled_format(content)

    # Try format 2: each line has energy + 7 + 3 = 11 values
    all_numeric_lines = []
    for line in lines:
        parts = line.split()
        try:
            vals = [float(x) for x in parts]
            all_numeric_lines.append(vals)
        except ValueError:
            continue

    if all_numeric_lines:
        # Check if lines have 11 values (energy + 7 + 3)
        lines_11 = [l for l in all_numeric_lines if len(l) == 11]
        if lines_11:
            energies = [l[0] for l in lines_11]
            d7_vectors = [l[1:8] for l in lines_11]
            d3_vectors = [l[8:11] for l in lines_11]
            # Return first frame's energy for single-energy comparison, or all
            return energies, d7_vectors, d3_vectors

        # Check if lines have 10 values (7 + 3, energy separate)
        lines_10 = [l for l in all_numeric_lines if len(l) == 10]
        if lines_10:
            d7_vectors = [l[0:7] for l in lines_10]
            d3_vectors = [l[7:10] for l in lines_10]
            # Try to find energy separately
            energy_lines = [l for l in all_numeric_lines if len(l) == 1]
            if energy_lines:
                energies = [l[0] for l in energy_lines]
            else:
                energies = [0.0] * len(lines_10)
            return energies, d7_vectors, d3_vectors

        # Try: first line is energy, then alternating d7/d3 lines
        if len(all_numeric_lines) >= 3:
            if len(all_numeric_lines[0]) == 1:
                energy = all_numeric_lines[0][0]
                d7_vectors = []
                d3_vectors = []
                i = 1
                while i < len(all_numeric_lines):
                    if i < len(all_numeric_lines) and len(all_numeric_lines[i]) == 7:
                        d7_vectors.append(all_numeric_lines[i])
                        i += 1
                    if i < len(all_numeric_lines) and len(all_numeric_lines[i]) == 3:
                        d3_vectors.append(all_numeric_lines[i])
                        i += 1
                    else:
                        i += 1
                if d7_vectors and d3_vectors:
                    return [energy] * len(d7_vectors), d7_vectors, d3_vectors

    raise ValueError(f"Could not parse file {filepath} in any known format")


def parse_labeled_format(content):
    """Parse labeled format with section headers."""
    # Extract total energy
    energy_match = re.search(r'Total energy:\s*([-\d.eE+]+)', content)
    if energy_match is None:
        # Try alternative: just a float on its own line labeled differently
        energy_match = re.search(r'[Ee]nergy[:\s]+([-\d.eE+]+)', content)

    if energy_match:
        energy = float(energy_match.group(1))
    else:
        energy = 0.0

    # Extract 7-element D vectors
    d7_section = re.search(r'D \(7 element vector\):\s*\n(.*?)(?:\n\s*\n|\nD \(3 element vector\))', content, re.DOTALL)
    d7_vectors = []
    if d7_section:
        d7_lines = [line.strip() for line in d7_section.group(1).strip().split('\n') if line.strip()]
        for line in d7_lines:
            vals = [float(x) for x in line.split()]
            if len(vals) == 7:
                d7_vectors.append(vals)

    # Extract 3-element D vectors
    d3_section = re.search(r'D \(3 element vector\):\s*\n(.*)', content, re.DOTALL)
    d3_vectors = []
    if d3_section:
        d3_lines = [line.strip() for line in d3_section.group(1).strip().split('\n') if line.strip()]
        for line in d3_lines:
            vals = [float(x) for x in line.split()]
            if len(vals) == 3:
                d3_vectors.append(vals)

    energies = [energy] * max(len(d7_vectors), 1)
    return energies, d7_vectors, d3_vectors


def parse_gold_format(filepath):
    """Parse the gold file which may use labeled format."""
    with open(filepath, 'r') as <local-path>        content = f.read()

    lines = [line.strip() for line in content.strip().split('\n') if line.strip()]

    # Try labeled format first
    if 'Total energy:' in content:
        energies, d7_vectors, d3_vectors = parse_labeled_format(content)
        if d7_vectors and d3_vectors:
            return energies, d7_vectors, d3_vectors

    # Try numeric format
    all_numeric_lines = []
    for line in lines:
        parts = line.split()
        try:
            vals = [float(x) for x in parts]
            all_numeric_lines.append(vals)
        except ValueError:
            continue

    if all_numeric_lines:
        lines_11 = [l for l in all_numeric_lines if len(l) == 11]
        if lines_11:
            energies = [l[0] for l in lines_11]
            d7_vectors = [l[1:8] for l in lines_11]
            d3_vectors = [l[8:11] for l in lines_11]
            return energies, d7_vectors, d3_vectors

    raise ValueError(f"Could not parse gold file {filepath}")


def eval():
    pred_path = 'pred_results/pred_dinfo.txt'
    gold_path = './gold_results/pred_dinfo.txt'

    # Step 1: Check files exist
    if not os.path.exists(pred_path):
        return (False, f"Predicted output file not found: {pred_path}")
    if not os.path.exists(gold_path):
        return (False, f"Gold output file not found: {gold_path}")

    # Step 2: Parse both files
    try:
        pred_energies, pred_d7, pred_d3 = parse_dinfo_flexible(pred_path)
    except Exception as <local-path>        return (False, f"Failed to parse predicted output: {e}")

    try:
        gold_energies, gold_d7, gold_d3 = parse_gold_format(gold_path)
    except Exception as <local-path>        return (False, f"Failed to parse gold output: {e}")

    # Step 3: Basic structure checks
    if len(pred_d7) == 0:
        return (False, "No D7 vectors found in predicted output")
    if len(pred_d3) == 0:
        return (False, "No D3 vectors found in predicted output")

    # Check that D7 vectors have 7 elements
    for i, row in enumerate(pred_d7):
        if len(row) != 7:
            return (False, f"D7 vector {i} has {len(row)} elements, expected 7")

    # Check that D3 vectors have 3 elements
    for i, row in enumerate(pred_d3):
        if len(row) != 3:
            return (False, f"D3 vector {i} has {len(row)} elements, expected 3")

    # Step 4: Validate dimensions match gold
    n_frames = min(len(pred_d7), len(gold_d7))
    if n_frames == 0:
        return (False, "No matching frames between predicted and gold")

    if len(pred_d7) != len(gold_d7):
        return (False, f"Number of D7 frames mismatch: pred={len(pred_d7)}, gold={len(gold_d7)}")
    if len(pred_d3) != len(gold_d3):
        return (False, f"Number of D3 frames mismatch: pred={len(pred_d3)}, gold={len(gold_d3)}")

    # Step 5: Check for NaN/Inf in predicted values
    all_pred_vals = list(pred_energies)
    for v in pred_d7:
        all_pred_vals.extend(v)
    for v in pred_d3:
        all_pred_vals.extend(v)
    for val in all_pred_vals:
        if math.isnan(val) or math.isinf(val):
            return (False, f"Predicted output contains NaN or Inf values")

    # Step 6: Compute energy MAE
    # Use per-frame energies if available, otherwise single energy
    n_energy_frames = min(len(pred_energies), len(gold_energies))
    energy_errors = [abs(pred_energies[i] - gold_energies[i]) for i in range(n_energy_frames)]
    energy_mae = sum(energy_errors) / len(energy_errors) if energy_errors else 0.0
    # Threshold: generous 5 eV (allows for some offset)
    energy_threshold = 5.0

    # Step 7: Compute D7 MAE (average across all components and frames)
    d7_errors = []
    for pred_row, gold_row in zip(pred_d7, gold_d7):
        for pv, gv in zip(pred_row, gold_row):
            d7_errors.append(abs(pv - gv))
    d7_mae = sum(d7_errors) / len(d7_errors) if d7_errors else 0.0
    d7_threshold = 0.1  # Slightly relaxed threshold

    # Step 8: Compute D3 MAE (average across all components and frames)
    d3_errors = []
    for pred_row, gold_row in zip(pred_d3, gold_d3):
        for pv, gv in zip(pred_row, gold_row):
            d3_errors.append(abs(pv - gv))
    d3_mae = sum(d3_errors) / len(d3_errors) if d3_errors else 0.0
    d3_threshold = 0.1  # Slightly relaxed threshold

    # Step 9: Apply thresholds
    reasons = []
    passed = True

    if energy_mae > energy_threshold:
        passed = False
        reasons.append(f"Energy MAE {energy_mae:.4f} eV exceeds threshold {energy_threshold} eV")

    if d7_mae > d7_threshold:
        passed = False
        reasons.append(f"D7 vector MAE {d7_mae:.6f} exceeds threshold {d7_threshold}")

    if d3_mae > d3_threshold:
        passed = False
        reasons.append(f"D3 vector MAE {d3_mae:.6f} exceeds threshold {d3_threshold}")

    if passed:
        return (True, f"All checks passed. Energy MAE: {energy_mae:.4f}, D7 MAE: {d7_mae:.6f}, D3 MAE: {d3_mae:.6f}")
    else:
        return (False, "; ".join(reasons))


