        return False

    def get_param_matching(params, patterns):
        """Get value of first key matching any pattern."""
        for key in params:
            for pattern in patterns:
                if pattern.lower() in key.lower():
                    return params[key]
        return None

    # Check required parameters are present - use flexible matching
    # gamma can appear as 'gamma_c', 'gamma_o', 'gamma', etc.
    # gammaw can appear as 'gammaw_c', 'gammaw_o', 'gammaw', etc.
    required_param_patterns = [
        (["devdw"], "Devdw (well depth)"),
        (["gamma"], "gamma parameter"),
        (["gammaw"], "gammaw parameter"),
        (["alfa"], "alfa parameter"),
        (["vdw1"], "vdw1 parameter"),
        (["rvdw"], "rvdw parameter"),
    ]

    missing_params = []
    for patterns, description in required_param_patterns:
        if not has_param_matching(pred_params, patterns):
            missing_params.append(description)

    if missing_params:
        return (False, f"Missing parameter(s) in pred_plevdw_params.txt: {missing_params}")

    # Check parameters are physically reasonable (not NaN or Inf)
    for key, val in pred_params.items():
        if math.isnan(val) or math.isinf(val):
            return (False, f"Parameter '{key}' has non-finite value: {val}")

    # Try to load gold params if available
    gold_params_path = os.path.join(gold_dir, "pred_plevdw_params.txt")
    gold_params = {}
    if os.path.exists(gold_params_path):
        gold_params = parse_params(gold_params_path)

        # Only check parameters that are unambiguous (pair-specific, not atom-specific)
        # devdw, alfa, rvdw are pair parameters - should match exactly
        # vdw1 is a global parameter - should match exactly
        unambiguous_checks = [
            (["devdw"], "devdw"),
            (["alfa"], "alfa"),
            (["rvdw"], "rvdw"),
            (["vdw1"], "vdw1"),
        ]
        for patterns, name in unambiguous_checks:
            pred_val = get_param_matching(pred_params, patterns)
            gold_val = get_param_matching(gold_params, patterns)
            if pred_val is not None and gold_val is not None:
                if abs(pred_val - gold_val) > 0.05:
                    return (False, f"Unambiguous parameter '{name}' mismatch: "
                                   f"pred={pred_val}, gold={gold_val}")

    # 4. Load and validate CSV data
    pred_csv_path = os.path.join(pred_dir, "pred_plevdw.csv")

    def load_csv(filepath):
        distances = []
        energies = []
        with open(filepath, "r") as <local-path>            reader = csv.reader(f)
            header = next(reader)  # skip header
            for row in reader:
                if len(row) >= 2:
                    try:
                        d = float(row[0])
                        e = float(row[1])
                        distances.append(d)
                        energies.append(e)
                    except ValueError:
                        pass
        return distances, energies

    pred_distances, pred_energies = load_csv(pred_csv_path)

    # Check minimum data points
    if len(pred_distances) < 20:
        return (False, f"Too few data points in CSV: {len(pred_distances)} (need at least 20)")

    # Check distance range covers ~2.0 to ~3.0
    if min(pred_distances) > 2.05:
        return (False, f"Distance range starts too high: {min(pred_distances):.4f} (should start near 2.0)")
    if max(pred_distances) < 2.95:
        return (False, f"Distance range ends too low: {max(pred_distances):.4f} (should end near 3.0)")

    # Check all values are finite
    for i, (d, e) in enumerate(zip(pred_distances, pred_energies)):
        if math.isnan(d) or math.isinf(d) or math.isnan(e) or math.isinf(e):
            return (False, f"Non-finite value at row {i}: distance={d}, energy={e}")

    # Check monotonically increasing distances
    for i in range(1, len(pred_distances)):
        if pred_distances[i] <= pred_distances[i - 1]:
            return (False, f"Distances not monotonically increasing at row {i}")

    # 5. Compare energy values against gold standard if available
    gold_csv_path = os.path.join(gold_dir, "pred_plevdw.csv")

    max_rel_error = 0.0
    max_abs_error = 0.0
    energy_comparison_done = False

    if os.path.exists(gold_csv_path):
        gold_distances, gold_energies = load_csv(gold_csv_path)

        if len(gold_distances) > 0:
            energy_comparison_done = True
            for gd, ge in zip(gold_distances, gold_energies):
                # Find closest pred distance
                best_idx = None
                best_dist_diff = float("inf")
                for i, pd_val in enumerate(pred_distances):
                    diff = abs(pd_val - gd)
                    if diff < best_dist_diff:
                        best_dist_diff = diff
                        best_idx = i

                if best_dist_diff > 0.05:
                    continue

                pe = pred_energies[best_idx]
                abs_error = abs(pe - ge)
                max_abs_error = max(max_abs_error, abs_error)
                if abs(ge) > 0.01:
                    rel_error = abs_error / abs(ge)
                    max_rel_error = max(max_rel_error, rel_error)

            # Use lenient tolerances since there's ambiguity in gamma/gammaw choice
            if max_rel_error > 0.30:
                return (False, f"Energy values differ too much from gold standard: "
                               f"max relative error = {max_rel_error:.4f} (threshold: 0.30)")
            if max_abs_error > 20.0:
                return (False, f"Energy values differ too much from gold standard: "
                               f"max absolute error = {max_abs_error:.4f} kcal/mol (threshold: 20.0)")

    # 6. Validate physical behavior: energy should generally decrease over the 2.0-3.0 range
    # (we're on the repulsive wall side, so energy decreases with distance)
    if pred_energies[0] < pred_energies[-1]:
        return (False, "Energy profile has unexpected shape: energy increases with distance in 2.0-3.0 range")

